===== CheckTelephoneUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;

/**
 * Rejects a create-owner request whose telephone is already used by another owner, so the
 * escalation handler can respond 409. Runs after {@link ValidateOwnerFields} has normalized the
 * telephone to E.164 and before {@link BuildOwner}; duplicates are detected by comparing these
 * E.164 values, so the national and international forms of one number collide.
 */
public class CheckTelephoneUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner existing : ownerRepository.findAll()) {
            if (telephone.equals(existing.getTelephone())) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}
===== CheckEmailUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;

/**
 * Rejects a create-owner request whose email is already used by another owner, so the escalation
 * handler can respond 409. Runs after {@link ValidateOwnerFields} has lower-cased the email and
 * before {@link BuildOwner}; duplicates are detected by comparing lower-cased values, so emails that
 * differ only in case collide. Email is optional, so a missing/blank email is accepted.
 */
public class CheckEmailUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        String normalized = email.toLowerCase(Locale.ROOT);
        for (Owner existing : ownerRepository.findAll()) {
            String existingEmail = existing.getEmail();
            if (existingEmail != null && normalized.equals(existingEmail.toLowerCase(Locale.ROOT))) {
                throw new DuplicateEmailException(normalized);
            }
        }
    }
}
===== CheckHouseholdUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a create-owner request whose last name and address are already used together by another
 * owner, so the escalation handler can respond 409. Last name is compared case-insensitively with
 * runs of whitespace collapsed to a single space; the address is compared in its normalized form
 * (see {@link AddressNormalizer}), so {@code "Smith"} at {@code "1  Main  St"} collides with
 * {@code "smith"} at {@code "1 Main Street"}.
 *
 * <p>Skipped when the request sets {@code sharesHousehold} true: the caller has confirmed the two
 * owners intentionally share a household, so the duplicate is allowed. Runs within the same write
 * transaction as the insert so the check and the insert see one consistent view.
 */
public class CheckHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = AddressNormalizer.normalize(request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }

    /** Lower-cases and collapses runs of whitespace to a single space, trimmed. Used for last name. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== AssignHouseholdId =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code householdId}: a stable identifier shared by all owners who live in the
 * same household, i.e. share a last name and address. It is the first 12 upper-cased hex characters
 * of the SHA-256 of {@code '<lastName>|<address>'}, with the last name normalized exactly as
 * {@link CheckHouseholdUnique} normalizes it (lower-cased, runs of whitespace collapsed, trimmed) and
 * the address normalized to its canonical form (see {@link AddressNormalizer}).
 *
 * <p>Because the id derives only from that normalized pair, two owners who intentionally share a
 * household (accepted via {@code sharesHousehold}) deterministically receive the same value without
 * any lookup. Runs after {@link BuildOwner} has mapped the request onto the entity and before
 * {@link SaveOwner}, so the assigned id is persisted and returned.
 */
public class AssignHouseholdId {

    public void service(@Val Owner owner) {
        String key = normalize(owner.getLastName()) + "|" + AddressNormalizer.normalize(owner.getAddress());
        owner.setHouseholdId(shaHex(key, 12));
    }

    /** Lower-cases and collapses runs of whitespace to a single space, trimmed. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    /** First {@code n} upper-case hex characters of SHA-256 of {@code value}. */
    private static String shaHex(String value, int n) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02X", b));
            }
            return sb.substring(0, n);
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}
===== AddressNormalizer =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Canonical address normalization applied whenever an owner is created. The create pipeline rewrites
 * the request's address to this form before it is stored and returned, and both household duplicate
 * detection ({@link CheckHouseholdUnique}) and the shared {@code householdId}
 * ({@link AssignHouseholdId}) compare addresses in this form.
 *
 * <p>Trims and collapses runs of whitespace to a single space, upper-cases, and expands common
 * abbreviations token by token: {@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}. So
 * {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}. The transformation is idempotent, so
 * re-normalizing an already-normalized address leaves it unchanged.
 */
final class AddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private AddressNormalizer() {
    }

    /** Returns the normalized address, or {@code ""} when {@code value} is null or blank. */
    static String normalize(String value) {
        if (value == null || value.isBlank()) {
            return "";
        }
        String[] tokens = value.trim().toUpperCase().split("\\s+");
        StringBuilder sb = new StringBuilder(value.length());
        for (String token : tokens) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(token, token));
        }
        return sb.toString();
    }
}
===== OwnerEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Shared handling of the optional owner {@code email}: when present it must be a syntactically
 * valid address, and is stored (and later returned) lower-cased. Absent or blank email is accepted.
 *
 * <p>Used by both create ({@link ValidateOwnerFields}) and update ({@link ValidateOwner}) so the two
 * endpoints treat email identically.
 */
final class OwnerEmail {

    /**
     * Practical RFC-5322-ish syntactic check: a non-empty local part, an {@code @}, and a dotted
     * domain ending in a letter-only TLD of at least two characters. Rejects values with whitespace
     * or a missing {@code @}/domain (e.g. {@code not-an-email}).
     */
    private static final Pattern EMAIL = Pattern.compile(
        "^[\\w!#$%&'*+/=?`{|}~^-]+(?:\\.[\\w!#$%&'*+/=?`{|}~^-]+)*"
            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z]{2,}$");

    private OwnerEmail() {
    }

    /**
     * Validates and normalizes the email on the request in place. When an email is present but not
     * syntactically valid, adds {@code "email"} to {@code errors} (a 400). When valid, rewrites it
     * lower-cased so persistence and the response carry the canonical form. Absent/blank is a no-op.
     */
    static void normalize(OwnerFieldsDto request, List<String> errors) {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        if (!EMAIL.matcher(email).matches()) {
            errors.add("email");
            return;
        }
        request.setEmail(email.toLowerCase(Locale.ROOT));
    }
}

