 * {@code householdId}) with different telephones have different keys and are both allowed; only an
 * exact full-key match is a duplicate. Runs after {@link ValidateOwnerFields} has normalized the
 * telephone (E.164), email (lower-cased) and address, and within the write transaction so the check
 * and the insert see one consistent view.
 */
public class CheckIdentityUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String householdId = OwnerIdentity.householdId(request.getLastName(), request.getAddress());
        String identityKey = OwnerIdentity.identityKey(request.getTelephone(), request.getEmail(), householdId);
        for (Owner existing : ownerRepository.findAll()) {
            String existingKey = OwnerIdentity.identityKey(existing.getTelephone(), existing.getEmail(),
                    existing.getHouseholdId());
            if (identityKey.equals(existingKey)) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}

