package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The single duplicate check for the create-owner endpoint. It consolidates the former separate
 * telephone, email and household checks into one derived {@code identityKey}
 * ({@code normalizedTelephone|email|householdId}, see {@link OwnerIdentity}) which is computed for the
 * incoming request and every existing owner, and rejects (409) when a new owner collides with an
 * existing one on that key.
 *
 * <p>Because the normalized telephone leads the key, two members of the same household (same
 * {@code householdId}) with different telephones never collide and are both allowed — a change from
 * the former household check, which rejected them regardless of telephone. Runs after
 * {@link ValidateOwnerFields} has normalized the telephone (E.164), email (lower-cased) and address,
 * and within the write transaction so the check and the insert see one consistent view.
 */
public class CheckIdentityUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String householdId = OwnerIdentity.householdId(request.getLastName(), request.getAddress());
        String identityKey = OwnerIdentity.identityKey(request.getTelephone(), request.getEmail(), householdId);
        for (Owner existing : ownerRepository.findAll()) {
            if (OwnerIdentity.collides(request.getTelephone(), request.getEmail(),
                    existing.getTelephone(), existing.getEmail())) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
